<script setup>
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { renderMarkdown } from '@/utils/markdown'
import { ensureKnowledgeNames, kpLabel } from '@/utils/knowledgeNames'
import AppShell from '@/components/shell/AppShell.vue'
import { useChapterDiagnosticStore } from '@/stores/chapterDiagnosticStore'
const route = useRoute(), router = useRouter(), store = useChapterDiagnosticStore()
const error = ref('')
onMounted(async () => { ensureKnowledgeNames(); try { await store.load(route.params.sessionId) } catch { error.value = '诊断报告暂时无法加载，请稍后重试。' } })
</script>
<template><AppShell><template #topbar-title>章节诊断报告</template><main v-if="store.result" class="result"><p class="eyebrow">{{store.result.diagnostic_kind === 'retest' ? '复测结果' : '诊断结果'}}</p><h1 class="t-1">你的薄弱知识点</h1><section class="card card-pad"><p v-if="!store.result.weak_points?.length">本次覆盖的知识点未发现明显薄弱项，可以继续练习。</p><div v-for="item in store.result.weak_points" :key="item.knowledge_point_code" class="weak"><strong>{{item.name || item.knowledge_point_code}}</strong><span>{{Math.round(item.accuracy * 100)}}% · {{item.reason}}</span></div></section><p v-if="store.result.untested_points?.length" class="coverage-note">本次未覆盖 {{store.result.untested_points.length}} 个知识点，暂不判断其掌握情况。</p><section v-if="store.result.recommended_resources?.length" class="card card-pad"><h2>推荐学习资源</h2><ul><li v-for="resource in store.result.recommended_resources" :key="resource.id"><details><summary>{{resource.title}}</summary><div class="math resource-body" v-html="renderMarkdown(resource.body || '')" /></details></li></ul></section><section v-if="store.result.mastery_comparison?.before" class="card card-pad"><h2>掌握度变化</h2><p v-for="(before, code) in store.result.mastery_comparison.before" :key="code">{{kpLabel(code)}}：{{Math.round(before * 100)}}% → {{Math.round((store.result.mastery_comparison.after?.[code] ?? before) * 100)}}%</p></section><button class="primary" @click="router.push('/knowledge')">返回知识目录</button></main><p v-else-if="error" class="loading" role="alert">{{ error }}</p><p v-else class="loading" role="status">正在生成报告…</p></AppShell></template>
<style scoped>.result{max-width:820px;margin:auto;padding:28px 24px 80px;display:grid;gap:18px}.weak{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--border)}.weak span{color:var(--ink-2)}li{margin:12px 0}button{min-height:44px;padding:0 18px;border:0;border-radius:10px}.primary{background:var(--accent);color:#fff}@media(max-width:600px){.result{padding:18px 14px 60px}.weak{display:grid;gap:4px}}</style>

<style scoped>
.result{max-width:1000px;padding-top:40px;gap:20px}.result>.eyebrow{justify-self:start;margin:0;padding:6px 10px;border-radius:6px;background:var(--brand-soft-2);color:var(--brand-text);font-size:12px;font-weight:600}.result h1{margin:0 0 8px;font-size:30px}.result section{padding:26px 30px;border-radius:12px;box-shadow:var(--shadow-1)}.result h2{margin:0 0 18px;font-size:18px}.result .weak{align-items:center;min-height:64px;line-height:1.6}.result .weak:last-child{border-bottom:0}.result ul{margin:0;padding:0;list-style:none}.result li{margin:0;padding:16px 0;border-bottom:1px solid var(--border);line-height:1.7}.result li:last-child{border-bottom:0}.result li p{margin:8px 0 0;color:var(--ink-2)}.result>.primary{justify-self:start;background:var(--brand);min-width:160px;cursor:pointer}.result>.primary:focus-visible{outline:2px solid var(--brand);outline-offset:3px}.loading{padding:32px;color:var(--ink-2)}@media(max-width:600px){.result{padding:24px 14px 80px}.result section{padding:20px 16px}.result .weak{align-items:start}.result>.primary{width:100%}}
</style>

<style scoped>summary{min-height:44px;line-height:1.7;cursor:pointer;font-weight:600;color:var(--brand-text)}.resource-body{line-height:1.85;overflow-x:auto;overflow-wrap:anywhere}.coverage-note{margin:0;color:var(--ink-2);font-size:13px;line-height:1.7}summary:focus-visible{outline:2px solid var(--brand);outline-offset:3px}</style>
